const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("extrel_rpc_response_topic", msg.rpcResponseTopic);
flow.set("extrel_write_result", msg.writeResult || null);

flow.set("extrel_part_278", null);
flow.set("extrel_part_294", null);

return msg;

msg.baseAddr = 278;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 278,
    quantity: 1
};
return msg;

msg.baseAddr = 294;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 294,
    quantity: 1
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for baseAddr " + msg.baseAddr);
    return null;
}

const baseAddr = msg.baseAddr;

if (baseAddr === 278) {
    flow.set("extrel_part_278", data[0]);
    flow.set("extrel_reg278_current", data[0]); // Store for bit manipulation in write
} else if (baseAddr === 294) {
    flow.set("extrel_part_294", data[0]);
}

// Check if all parts received
const part278 = flow.get("extrel_part_278");
const part294 = flow.get("extrel_part_294");

if (part278 === null || part278 === undefined ||
    part294 === null || part294 === undefined) {
    return null;
}

msg.reg278 = part278;
msg.reg294 = part294;
return msg;

const reg278 = msg.reg278;
const reg294 = msg.reg294;

// Clear flow context
flow.set("extrel_part_278", null);
flow.set("extrel_part_294", null);

// Parse reg278 Bit8-9 (10=disable, 11=enable)
const relayBits = (reg278 >> 8) & 0x03;
const externalRelayFeatureEnabled = relayBits === 0x03;

// Parse relay bitmap (reg294 Bit0-7)
const relayBitmapRaw = reg294 & 0xFF;

// Build relays array - only relayId (0-7) and normallyOpen
const relays = [];
for (let i = 0; i < 8; i++) {
    const isActive = ((relayBitmapRaw >> i) & 0x01) === 1;
    relays.push({
        relayId: i,
        normallyOpen: isActive
    });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "ExternalRelayConfigState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    gatewayId: gatewayId,
    externalRelayFeatureEnabled: externalRelayFeatureEnabled,
    relayBitmapRaw: relayBitmapRaw,
    relays: relays
};

// Check if this is after a write
const writeResult = flow.get("extrel_write_result");
flow.set("extrel_write_result", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Updated ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

node.status({ fill: "green", shape: "dot", text: externalRelayFeatureEnabled ? "Enabled" : "Disabled" });

return msg;

const params = msg.rpcParams || {};
const writes = [];

// 278 Bit8-9: externalRelayFeatureEnabled (will need to read first)
if (params.externalRelayFeatureEnabled !== undefined) {
    writes.push({ register: 278, param: "feature", enabled: params.externalRelayFeatureEnabled, name: "Ext Relay Feature" });
}

// 294: relayBitmapRaw
if (params.relayBitmapRaw !== undefined) {
    const val = params.relayBitmapRaw & 0xFF;
    writes.push({ register: 294, value: val, name: "Relay Bitmap" });
}

// If relays array provided, build bitmap
if (params.relays && Array.isArray(params.relays)) {
    let bitmap = 0;
    for (const relay of params.relays) {
        if (relay.relayId >= 0 && relay.relayId <= 7 && relay.normallyOpen) {
            bitmap |= (1 << relay.relayId);
        }
    }
    // Check if we already have a write for 294
    const existing = writes.find(w => w.register === 294);
    if (existing) {
        existing.value = bitmap;
    } else {
        writes.push({ register: 294, value: bitmap, name: "Relay Bitmap" });
    }
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    return null;
}

global.set("extrel_write_queue", writes);
global.set("extrel_write_index", 0);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return msg;

const writes = global.get("extrel_write_queue") || [];
const index = global.get("extrel_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

// If register 278, need to do bit manipulation
if (current.register === 278) {
    // Read reg278 first if not already read
    const reg278Current = flow.get("extrel_reg278_current");
    if (reg278Current === null || reg278Current === undefined) {
        // Need to read it first
        msg.needRead278 = true;
        msg.payload = {
            fc: 3,
            unitid: 1,
            address: 278,
            quantity: 1
        };
        msg.currentWrite = current;
        return [msg, null];
    }

    // We have the value, do bit manipulation
    let newVal = reg278Current & ~0x0300; // Clear bits 8-9
    if (current.enabled) {
        newVal = newVal | 0x0300; // Set bits 8-9 (11)
    } else {
        newVal = newVal | 0x0200; // Set bit 9, clear bit 8 (10)
    }

    msg.payload = {
        fc: 16,
        unitid: 1,
        address: 278,
        quantity: 1,
        value: [newVal]
    };
    msg.currentWrite = current;
    msg.needRead278 = false;

    node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });
    return [null, msg];
}

// Regular write for other registers
msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;
msg.needRead278 = false;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return [null, msg];

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

const reg278 = Array.isArray(data) ? data[0] : 0;
flow.set("extrel_reg278_current", reg278);

// Now retry the prepare write
return msg;

const writes = global.get("extrel_write_queue") || [];
let index = global.get("extrel_write_index") || 0;

const current = msg.currentWrite;
const results = global.get("extrel_write_results") || [];

if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value || current.enabled,
        success: true
    });
    global.set("extrel_write_results", results);
}

index++;
global.set("extrel_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done - trigger read
msg.writeResult = {
    count: results.length,
    writes: results
};

global.set("extrel_write_queue", null);
global.set("extrel_write_index", null);
global.set("extrel_write_results", null);

return [null, msg];

const rpcTopic = flow.get("extrel_rpc_response_topic");
flow.set("extrel_rpc_response_topic", null);

if (!rpcTopic) {
    return null;
}

msg.topic = rpcTopic;
return msg;
